// The status endpoint answers either
//   { running: true,  startedAt, out }
//   { running: false, code, out, finishedAt }
// and this flattens whichever arrived into the same shape the
// Execute Command workflow produces, so notifiers are interchangeable.

const r = $input.first().json;
const out = String(r.out || '').trim();

if (r.running) {
  return [{
    json: {
      ok: false,
      timedOut: true,
      exitCode: null,
      succeeded: 0,
      failed: 0,
      seconds: null,
      stores: [],
      failedStores: [],
      text: 'Ingest still running after 60 minutes — stopped watching. It may yet finish; check /api/ingest/status.',
      log: out.slice(-4000),
    },
  }];
}

const lines = out.split('\n').map(l => l.trim());
const summary = out.match(/(\d+) succeeded · (\d+) failed · (\d+)s/);

// A ✓/✗ line in the summary block always carries the store id. Requiring that
// id keeps preflight errors — which also start with ✗, but are about
// credentials rather than a store — out of the failed list.
const storeLines = lines.filter(l => /^[✓✗]\s+\d+\s/.test(l));
const failedStores = storeLines.filter(l => l.startsWith('✗'));
const blocker = lines.find(l => l.startsWith('✗') && !/^✗\s+\d+\s/.test(l)) || null;

const idle = /nothing to do|0 to ingest/.test(out);
const exitCode = Number(r.code ?? 1);

let text;
if (summary) {
  text = `Shopify ingest: ${summary[1]} succeeded, ${summary[2]} failed in ${summary[3]}s`;
} else if (idle) {
  text = 'Nothing new on Drive — every store and date is already ingested';
} else if (blocker) {
  text = `Shopify ingest never started — ${blocker.replace(/^✗\s*/, '')}`;
} else {
  text = `Shopify ingest exited ${exitCode} without a summary — check the log`;
}

return [{
  json: {
    ok: exitCode === 0,
    timedOut: false,
    idle,
    exitCode,
    succeeded: summary ? Number(summary[1]) : 0,
    failed: summary ? Number(summary[2]) : failedStores.length,
    seconds: summary ? Number(summary[3]) : null,
    stores: storeLines,
    failedStores,
    blocker,
    text,
    log: out.slice(-4000),
  },
}];
